#include "Monstey_FearDbPacked.hpp"
#include "Monstey_Json.hpp"
#include <array>
#include <bit>
#include <fstream>
#include <iostream>
#include <vector>
using namespace Monstey;
namespace {
using Monstey_U32=std::uint32_t;
static_assert(std::endian::native==std::endian::little,"Qualified owned Windows byte representation");
std::uint64_t Monstey_Groups=0,Monstey_Cases=0,Monstey_Checks=0;
void Monstey_Check(bool value,const char*text){++Monstey_Checks;if(!value)throw std::runtime_error(text);}
void Monstey_Add(std::vector<std::uint8_t>&bytes,Monstey_U32 word){for(unsigned i=0;i<4;++i)bytes.push_back(static_cast<std::uint8_t>(word>>(8*i)));}
std::vector<std::uint8_t> Monstey_Wire(Monstey_U32 pool,Monstey_U32 spare,std::size_t prefix=0){std::vector<std::uint8_t> wire(prefix,0xcd);for(auto x:std::array<Monstey_U32,7>{0x42444147,3,pool,spare,0,0,0})Monstey_Add(wire,x);wire.resize(prefix+28u+pool,0x61);Monstey_Add(wire,0);return wire;}
std::size_t Monstey_Extent(std::uint64_t value){for(std::size_t i=0;i<sizeof(std::size_t);++i)if(((value>>(8*i))&255u)==0)return i+1;throw std::runtime_error("Numeric fixture has no declared terminator");}
Monstey_U32 Monstey_Get(const Monstey_FearDbPackedImage&image,Monstey_U32 address){Monstey_U32 value=0;for(unsigned i=0;i<4;++i)value|=Monstey_U32(image.allocation.at(address-image.base+i))<<(8*i);return value;}
void Monstey_CheckImage(const Monstey_FearDbPackedLoad&loaded,Monstey_U32 pool,Monstey_U32 spare,std::size_t first_extent,std::size_t graph_extent,std::uint64_t live_name){const auto allocation=pool+20u+spare*16u+static_cast<Monstey_U32>(first_extent);const auto used=pool+20u+static_cast<Monstey_U32>(graph_extent);Monstey_Check(loaded.status==Monstey_FearDbPackedStatus::loaded&&loaded.image.has_value(),"safe native alias loads");const auto&image=*loaded.image;Monstey_Check(loaded.allocation_bytes==allocation&&image.allocation.size()==allocation,"allocation retains after-header extent");Monstey_Check(image.used_bytes==used&&image.database==image.base+pool,"graph uses post-count extent");Monstey_Check(Monstey_Get(image,image.database+12)==image.base+used,"category array follows second measured name");Monstey_Check(Monstey_Get(image,image.database)==image.base&&Monstey_Get(image,image.database+4)==image.database+20&&Monstey_Get(image,image.database+8)==0&&Monstey_Get(image,image.database+16)==0,"database metadata and ownership unchanged");for(std::size_t i=0;i<graph_extent;++i)Monstey_Check(image.allocation.at(pool+20u+i)==static_cast<std::uint8_t>(live_name>>(8*i)),"live name copied through final terminator");for(std::size_t i=used;i<allocation;++i)Monstey_Check(image.allocation[i]==0,"owned unused tail placeholder unchanged");}
void Monstey_PositionCase(Monstey_U32 pool,Monstey_U32 spare,std::size_t prefix){auto wire=Monstey_Wire(pool,spare,prefix);const auto unchanged=wire;Monstey_FearDbPackedInput input{wire,prefix};const auto name=std::span<const std::uint8_t>(reinterpret_cast<const std::uint8_t*>(&input.position),sizeof(input.position));const auto first=Monstey_Extent(prefix+28u);const auto last=Monstey_Extent(prefix+32u+pool);const auto loaded=Monstey_FearDbLoadPacked(input,name,0x30000000);Monstey_CheckImage(loaded,pool,spare,first,last,prefix+32u+pool);Monstey_Check(input.position==prefix+32u+pool&&input.read_calls==3&&wire==unchanged,"concrete input calls advance and caller bytes unchanged");++Monstey_Cases;}
void Monstey_ExactCounterexample(){Monstey_PositionCase(228,1,0);auto wire=Monstey_Wire(228,1);Monstey_FearDbPackedInput input{wire};const auto alias=std::span<const std::uint8_t>(reinterpret_cast<const std::uint8_t*>(&input.position),sizeof(input.position));const auto result=Monstey_FearDbLoadPacked(input,alias,0x30000000);Monstey_Check(result.allocation_bytes==266&&result.image->used_bytes==251&&Monstey_Get(*result.image,result.image->database+12)==0x300000fb,"root exact266/251/300000FB regression");Monstey_Check(Monstey_Extent(28)==2&&Monstey_Extent(256)==1&&Monstey_Extent(260)==3,"three distinct sampling epochs discriminate old and early rescan");++Monstey_Cases;++Monstey_Groups;}
void Monstey_PositionMatrix(){for(auto prefix:std::array<std::size_t,9>{0,1,127,223,224,227,228,255,65503})for(auto pool:std::array<Monstey_U32,19>{0,1,2,3,219,220,223,224,225,226,227,228,229,230,251,252,255,256,257})for(auto spare:std::array<Monstey_U32,2>{1,2})Monstey_PositionCase(pool,spare,prefix);for(auto pool:std::array<Monstey_U32,3>{65504,65505,65761})Monstey_PositionCase(pool,1,0);++Monstey_Groups;}
void Monstey_ReadCounterAlias(){for(auto initial:std::array<std::uint64_t,6>{0,1,253,254,255,65534})for(auto pool:std::array<Monstey_U32,3>{0,1,228}){auto wire=Monstey_Wire(pool,1);Monstey_FearDbPackedInput input{wire,0,initial};const auto name=std::span<const std::uint8_t>(reinterpret_cast<const std::uint8_t*>(&input.read_calls),sizeof(input.read_calls));const auto result=Monstey_FearDbLoadPacked(input,name,0x30000000);Monstey_CheckImage(result,pool,1,Monstey_Extent(initial+1),Monstey_Extent(initial+3),initial+3);Monstey_Check(input.read_calls==initial+3&&input.position==pool+32u,"read-call field alias includes zero-byte pool Read");++Monstey_Cases;}++Monstey_Groups;}
void Monstey_RootReadFailure(){for(std::size_t size=256;size<260;++size){auto wire=Monstey_Wire(228,1);wire.resize(size);Monstey_FearDbPackedInput input{wire};const auto field=reinterpret_cast<const std::uint8_t*>(&input.position);const std::span<const std::uint8_t> name(field+1,1);const auto result=Monstey_FearDbLoadPacked(input,name,0x30000000);Monstey_Check(result.status==Monstey_FearDbPackedStatus::graph_read_failed&&!result.image&&result.allocation_bytes==265,"failed root Read precedes a now-unterminated graph name scan");Monstey_Check(input.position==256&&input.read_calls==3,"failed root Read keeps owned cursor and counts its call");++Monstey_Cases;}++Monstey_Groups;}
void Monstey_ConsumedSecondExtent(){auto wire=Monstey_Wire(228,1);Monstey_FearDbPackedInput input{wire};const auto field=reinterpret_cast<const std::uint8_t*>(&input.position);bool caught=false;try{(void)Monstey_FearDbLoadPacked(input,std::span<const std::uint8_t>(field+1,1),0x30000000);}catch(const std::invalid_argument&e){caught=std::string(e.what()).find("graph name")!=std::string::npos;}Monstey_Check(caught&&input.position==260&&input.read_calls==3,"second bounded name extent is checked only after successful root Read");++Monstey_Cases;++Monstey_Groups;}
void Monstey_ConsumedWriteBounds(){for(auto pool:std::array<Monstey_U32,5>{224,225,226,227,228}){auto wire=Monstey_Wire(pool,0);Monstey_FearDbPackedInput input{wire};const auto name=std::span<const std::uint8_t>(reinterpret_cast<const std::uint8_t*>(&input.position),sizeof(input.position));const auto first=Monstey_Extent(28),graph=Monstey_Extent(pool+32u);if(graph<=first){const auto result=Monstey_FearDbLoadPacked(input,name,0x30000000);Monstey_CheckImage(result,pool,0,first,graph,pool+32u);}else{bool caught=false;try{(void)Monstey_FearDbLoadPacked(input,name,0x30000000);}catch(const Monstey_FearDbFault&e){caught=e.address==0x30000000u+pool+20u+static_cast<Monstey_U32>(first)&&e.width==1&&e.writing;}Monstey_Check(caught,"larger live name does not silently resize initial allocation");}Monstey_Check(input.position==pool+32u&&input.read_calls==3,"copy fault does not issue later category reads");++Monstey_Cases;}++Monstey_Groups;}
void Monstey_FailedPoolAndHeader(){auto wire=Monstey_Wire(228,1);wire.resize(255);Monstey_FearDbPackedInput input{wire};const auto field=reinterpret_cast<const std::uint8_t*>(&input.position);const auto result=Monstey_FearDbLoadPacked(input,std::span<const std::uint8_t>(field+1,1),0x30000000);Monstey_Check(result.status==Monstey_FearDbPackedStatus::pool_read_failed&&!result.image&&input.position==28&&input.read_calls==2,"pool failure exits before root or graph name scan");++Monstey_Cases;auto bad=Monstey_Wire(228,1);bad[0]=0;Monstey_FearDbPackedInput invalid{bad};const auto header=Monstey_FearDbLoadPacked(invalid,{},0);Monstey_Check(header.status==Monstey_FearDbPackedStatus::invalid_header&&!header.image&&invalid.position==28&&invalid.read_calls==1,"invalid header consumes no name extent or allocation");++Monstey_Cases;++Monstey_Groups;}
}
int main(int argc,char**argv){try{if(argc!=2)throw std::runtime_error("NEW report required");Monstey_ExactCounterexample();Monstey_PositionMatrix();Monstey_ReadCounterAlias();Monstey_RootReadFailure();Monstey_ConsumedSecondExtent();Monstey_ConsumedWriteBounds();Monstey_FailedPoolAndHeader();std::ofstream(argv[1],std::ios::binary)<<Monstey_Json::object({{"schema","Monstey.FearPackedNameRescanTests/1"},{"passed",true},{"groups",Monstey_Groups},{"cases",Monstey_Cases},{"checks",Monstey_Checks},{"public_mutable_input_field_aliases",true},{"original_program_executed",false},{"native_out_of_allocation_execution_claimed",false}}).dump(2)<<'\n';std::cout<<"PASS "<<Monstey_Groups<<" groups "<<Monstey_Cases<<" cases "<<Monstey_Checks<<" checks\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
